/**
 * UTF-8 codec mirroring Python's `str.encode()` (default 'utf-8', 'strict').
 *
 * A "bytes object" is modelled throughout this project as a plain JavaScript
 * array of integers in [0, 255]. That keeps the byte pipeline free of any
 * typed-array / struct-view machinery: every value is an ordinary Number and
 * every transformation is plain arithmetic.
 */

const REPLACEMENT = 0xfffd;

/**
 * Encode a JavaScript string into a byte array using UTF-8.
 *
 * Surrogate pairs are combined into a single astral code point. Node has
 * already replaced malformed OS argv bytes with U+FFFD before we ever see
 * them, so a stray lone surrogate can only come from inside the process; it is
 * folded to U+FFFD rather than throwing.
 *
 * @param {string} text
 * @returns {number[]} UTF-8 bytes
 */
export function encodeUtf8(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) {
    let cp = text.charCodeAt(i);

    if (cp >= 0xd800 && cp <= 0xdbff) {
      const low = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (low >= 0xdc00 && low <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (low - 0xdc00);
        i += 1;
      } else {
        cp = REPLACEMENT;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = REPLACEMENT;
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

