/**
 * Python `repr()` for the two types this program prints or embeds in error
 * messages: `bytes` and `str`.
 */

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;

/** Short escapes CPython emits instead of a \xNN sequence. */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

function hex2(value) {
  return `\\x${value.toString(16).padStart(2, '0')}`;
}

/**
 * Pick the quote character CPython would use: a single quote normally, but a
 * double quote when the payload contains a single quote and no double quote.
 */
function chooseQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
}

/**
 * `repr()` of a bytes object, e.g. [0x6b, 0xd4] -> `b'k\xd4'`.
 *
 * @param {number[]} data byte values in [0, 255]
 * @returns {string}
 */
export function reprBytes(data) {
  const quote = chooseQuote(data.includes(SINGLE_QUOTE), data.includes(DOUBLE_QUOTE));
  let out = `b${String.fromCharCode(quote)}`;

  for (const byte of data) {
    if (byte === BACKSLASH || byte === quote) {
      out += `\\${String.fromCharCode(byte)}`;
    } else if (SHORT_ESCAPES.has(byte)) {
      out += SHORT_ESCAPES.get(byte);
    } else if (byte >= 0x20 && byte < 0x7f) {
      out += String.fromCharCode(byte);
    } else {
      out += hex2(byte);
    }
  }

  return out + String.fromCharCode(quote);
}

/**
 * `repr()` of a str, used by argparse when quoting a rejected value.
 *
 * Printable non-ASCII code points survive verbatim (Python 3 keeps them);
 * C0/C1 control characters become \xNN, matching CPython for every character
 * class that can realistically reach us from the command line.
 *
 * @param {string} text
 * @returns {string}
 */
export function reprStr(text) {
  const quote = String.fromCharCode(
    chooseQuote(text.includes("'"), text.includes('"')),
  );
  let out = quote;

  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (ch === '\\' || ch === quote) {
      out += `\\${ch}`;
    } else if (SHORT_ESCAPES.has(cp)) {
      out += SHORT_ESCAPES.get(cp);
    } else if (cp < 0x20 || cp === 0x7f || (cp >= 0x80 && cp <= 0x9f)) {
      out += hex2(cp);
    } else {
      out += ch;
    }
  }

  return out + quote;
}

