/**
 * Python's `int(str)` conversion.
 *
 * Values are returned as BigInt because Python integers are unbounded and this
 * program feeds them straight into range checks and a modulo: `--f
 * 99999999999999999999` has to survive intact so the resulting error message
 * can quote it exactly.
 */

/** Characters CPython's integer parser treats as surrounding whitespace. */
const WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

const DECIMAL_DIGIT = /\p{Nd}/u;

function isWhitespace(ch) {
  const cp = ch.codePointAt(0);
  return WHITESPACE.has(cp) || (cp >= 0x2000 && cp <= 0x200a);
}

/**
 * Numeric value of any Unicode decimal digit (`int('٣')` is 3 in Python).
 *
 * Decimal-digit blocks are contiguous runs of ten code points, so the digit's
 * value is its offset from the run's start.
 */
function digitValue(ch) {
  if (!DECIMAL_DIGIT.test(ch)) return -1;
  const cp = ch.codePointAt(0);
  for (let offset = 0; offset <= 9; offset += 1) {
    const zero = cp - offset;
    if (!DECIMAL_DIGIT.test(String.fromCodePoint(zero))) break;
    if (zero === 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(zero - 1))) {
      return offset;
    }
  }
  return -1;
}

function strip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isWhitespace(chars[start])) start += 1;
  while (end > start && isWhitespace(chars[end - 1])) end -= 1;
  return chars.slice(start, end);
}

/**
 * Parse a base-10 integer literal exactly as CPython's `int()` does: optional
 * surrounding whitespace, one optional ASCII sign, decimal digits, and
 * underscores that must sit between two digits.
 *
 * @param {string} text
 * @returns {bigint|null} the value, or null when Python would raise ValueError
 */
export function pyInt(text) {
  const chars = strip(text);
  let index = 0;

  let negative = false;
  if (chars[index] === '+' || chars[index] === '-') {
    negative = chars[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const ch = chars[index];
    if (ch === '_') {
      if (!previousWasDigit) return null;
      previousWasDigit = false;
      continue;
    }
    const value = digitValue(ch);
    if (value < 0) return null;
    digits += String(value);
    previousWasDigit = true;
  }

  if (!previousWasDigit) return null; // empty, or a trailing underscore
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/**
 * Python's `%` operator, which floors toward negative infinity rather than
 * truncating toward zero the way JavaScript's `%` does.
 *
 * @param {bigint} left
 * @param {bigint} right
 * @returns {bigint}
 */
export function pyMod(left, right) {
  const remainder = left % right;
  return remainder !== 0n && remainder < 0n !== right < 0n
    ? remainder + right
    : remainder;
}

