/**
 * Reproduction of the interpreter-level failure output.
 *
 * The reference binary is a PyInstaller bundle, so an uncaught exception ends
 * with a Python traceback on stderr and exit status 1. Each construct call
 * site has a fixed frame list, which callers supply so the traceback matches
 * the original line for line.
 */

/** Raised in place of Python's `SystemExit`; carries the process exit status. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * A Python exception that reaches the top level: it knows its dotted type
 * name, its `str()` form, and the stack of frames leading to it.
 */
export class PythonException extends Error {
  /**
   * @param {string} typeName dotted name, e.g. 'construct.core.StreamError'
   * @param {string} text the exception's str() value
   * @param {{file: string, line: number, name: string}[]} frames innermost last
   * @param {?PythonException} cause exception being handled when this was raised
   */
  constructor(typeName, text, frames, cause = null) {
    super(`${typeName}: ${text}`);
    this.name = typeName;
    this.typeName = typeName;
    this.text = text;
    this.frames = frames;
    this.pythonCause = cause;
  }
}

function formatTraceback(exc) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of exc.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(`${exc.typeName}: ${exc.text}`);
  return lines.join('\n');
}

/**
 * Write the traceback (including any chained "during handling" section) to
 * stderr, followed by PyInstaller's own bootloader complaint.
 *
 * @param {PythonException} exc
 * @param {string} scriptName script name PyInstaller reports, e.g. 'test17'
 */
export function printPythonTraceback(exc, scriptName) {
  const blocks = [];
  for (let current = exc; current; current = current.pythonCause) {
    blocks.unshift(formatTraceback(current));
  }
  const joined = blocks.join(
    '\n\nDuring handling of the above exception, another exception occurred:\n\n',
  );
  process.stderr.write(`${joined}\n`);
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`,
  );
}

