/**
 * The construct exception hierarchy, limited to what building can raise.
 *
 * `ConstructError` prefixes the message with the path when one is given, which
 * is why every failure here reads "Error in path (building)" on its own line
 * before the specific complaint.
 */

import { PythonException } from '../python/traceback.mjs';

export class ConstructError extends PythonException {
  constructor(typeName, message, path, frames, cause = null) {
    const text = path === null || path === undefined
      ? message
      : `Error in path ${path}\n${message}`;
    super(typeName, text, frames, cause);
  }
}

export class StreamError extends ConstructError {
  constructor(message, path, frames) {
    super('construct.core.StreamError', message, path, frames);
  }
}

export class FormatFieldError extends ConstructError {
  constructor(message, path, frames, cause) {
    super('construct.core.FormatFieldError', message, path, frames, cause);
  }
}

/** The bare `struct.error` that FormatField catches and re-raises. */
export class StructError extends PythonException {
  constructor(message, frames) {
    super('struct.error', message, frames);
  }
}

