/**
 * construct's `stream_write` guard.
 *
 * Building a fixed-size field checks the requested length before comparing it
 * against the payload, so a negative size is reported even when the payload
 * length also disagrees.
 */

import { StreamError } from './errors.mjs';

/** Frames the caller has already walked through when reaching this check. */
const CALLER_FRAMES = [
  { file: 'construct/core.py', line: 452, name: 'build' },
  { file: 'construct/core.py', line: 464, name: 'build_stream' },
  { file: 'construct/core.py', line: 970, name: '_build' },
];

const NEGATIVE_LENGTH_LINE = 193;
const WRONG_LENGTH_LINE = 195;

/**
 * Validate that `data` is exactly `length` bytes long.
 *
 * @param {number[]} data
 * @param {bigint} length requested field width
 * @param {string} path construct path shown in the error
 * @param {{file: string, line: number, name: string}[]} outerFrames caller frames
 * @throws {StreamError}
 */
export function streamWrite(data, length, path, outerFrames) {
  const framesTo = (line) => [
    ...outerFrames,
    ...CALLER_FRAMES,
    { file: 'construct/core.py', line, name: 'stream_write' },
  ];

  if (length < 0n) {
    throw new StreamError(
      `length must be non-negative, found ${length}`,
      path,
      framesTo(NEGATIVE_LENGTH_LINE),
    );
  }
  if (BigInt(data.length) !== length) {
    throw new StreamError(
      `bytes object of wrong length, expected ${length}, found ${data.length}`,
      path,
      framesTo(WRONG_LENGTH_LINE),
    );
  }
}

