/**
 * `FormatField` — construct's fixed-width integer fields (`Int8ul`, `Int16ul`,
 * and friends), which delegate to `struct.pack` under the hood.
 *
 * Bytes are produced by shifting and masking BigInt values, so arbitrarily
 * large out-of-range inputs are reported verbatim instead of being silently
 * rounded on the way in.
 */

import { FormatFieldError, StructError } from './errors.mjs';

const STRUCT_ERROR_LINE = 1165;
const BUILD_FRAMES = [
  { file: 'construct/core.py', line: 452, name: 'build' },
  { file: 'construct/core.py', line: 464, name: 'build_stream' },
  { file: 'construct/core.py', line: 1167, name: '_build' },
];

export class FormatField {
  /**
   * @param {string} endianness '<' little-endian or '>' big-endian
   * @param {string} code struct format character, e.g. 'B'
   * @param {number} byteCount field width in bytes
   * @param {boolean} signed
   */
  constructor(endianness, code, byteCount, signed) {
    this.endianness = endianness;
    this.code = code;
    this.byteCount = byteCount;
    this.signed = signed;
    this.fmtstr = `${endianness}${code}`;

    const span = 1n << BigInt(byteCount * 8);
    this.minimum = signed ? -(span / 2n) : 0n;
    this.maximum = signed ? span / 2n - 1n : span - 1n;
  }

  /**
   * Build the field, mirroring `Int8ul.build(value)`.
   *
   * @param {bigint} value
   * @param {{file: string, line: number, name: string}[]} outerFrames call site
   * @returns {number[]} packed bytes
   * @throws {FormatFieldError} when the value does not fit the format
   */
  build(value, outerFrames = []) {
    if (value < this.minimum || value > this.maximum) {
      const cause = new StructError(
        `'${this.code}' format requires ${this.minimum} <= number <= ${this.maximum}`,
        [{ file: 'construct/core.py', line: STRUCT_ERROR_LINE, name: '_build' }],
      );
      throw new FormatFieldError(
        `struct '${this.fmtstr}' error during building, given value ${value}`,
        '(building)',
        [...outerFrames, ...BUILD_FRAMES],
        cause,
      );
    }

    const unsigned = value < 0n ? value + (1n << BigInt(this.byteCount * 8)) : value;
    const bytes = [];
    for (let i = 0; i < this.byteCount; i += 1) {
      bytes.push(Number((unsigned >> BigInt(i * 8)) & 0xffn));
    }
    return this.endianness === '<' ? bytes : bytes.reverse();
  }
}

