/**
 * A small `argparse.ArgumentParser` work-alike covering the features this CLI
 * uses: long options with required values, `--opt=value`, unique-prefix
 * abbreviation, `-h/--help`, required-argument checking, and the usage/error
 * output format.
 */

import { pyInt } from '../python/int.mjs';
import { reprStr } from '../python/repr.mjs';
import { SystemExit } from '../python/traceback.mjs';

/** argparse's default help column, and the indent it hangs entries at. */
const INDENT = '  ';
const MAX_HELP_POSITION = 24;

/** `type=int`: returns a BigInt, or null to signal ValueError. */
export const intType = { name: 'int', convert: pyInt };

/** `type=str`: the identity conversion. */
export const strType = { name: 'str', convert: (value) => value };

export class ArgumentParser {
  /** @param {{prog: string}} options program name used in messages */
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [
      { flags: ['-h', '--help'], dest: 'help', help: 'show this help message and exit', isHelp: true },
    ];
  }

  /**
   * @param {string} flag long option string, e.g. '--a'
   * @param {{type: object, required: boolean}} spec
   */
  addArgument(flag, { type, required }) {
    const dest = flag.replace(/^--?/, '');
    this.actions.push({
      flags: [flag],
      dest,
      type,
      required,
      metavar: dest.toUpperCase(),
      isHelp: false,
    });
  }

  formatUsage() {
    const parts = this.actions.map((action) => (action.isHelp
      ? '[-h]'
      : `${action.flags[0]} ${action.metavar}`));
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => (action.isHelp
      ? '-h, --help'
      : `${action.flags[0]} ${action.metavar}`));
    const width = Math.min(
      Math.max(...invocations.map((text) => text.length)) + 2,
      MAX_HELP_POSITION,
    );

    let out = `${this.formatUsage()}\noptions:\n`;
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      out += action.help
        ? `${INDENT}${invocation.padEnd(width)}${action.help}\n`
        : `${INDENT}${invocation}\n`;
    });
    return out;
  }

  /** Print usage plus `prog: error: message` to stderr and exit with status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Resolve an option string to an action, honouring unique-prefix
   * abbreviation the way argparse does.
   */
  lookup(optionString) {
    const exact = this.actions.find((action) => action.flags.includes(optionString));
    if (exact) return exact;

    if (!optionString.startsWith('--')) return null;
    const candidates = this.actions.filter((action) => action.flags.some(
      (flag) => flag.startsWith('--') && flag.startsWith(optionString),
    ));
    if (candidates.length === 1) return candidates[0];
    if (candidates.length > 1) {
      const matches = candidates.map((action) => action.flags.find((flag) => flag.startsWith(optionString)));
      this.error(`ambiguous option: ${optionString} could match ${matches.join(', ')}`);
    }
    return null;
  }

  /**
   * Parse `argv` (the program's own arguments, without argv[0]).
   *
   * @param {string[]} argv
   * @returns {Object<string, bigint|string>} the populated namespace
   * @throws {SystemExit} on `--help` or any usage error
   */
  parseArgs(argv) {
    const namespace = Object.create(null);
    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i += 1) {
      const arg = argv[i];

      // A bare `--` and everything after it has nowhere to go: this parser
      // defines no positionals, so argparse reports the lot as unrecognized.
      if (arg === '--') {
        extras.push(...argv.slice(i));
        break;
      }

      if (!arg.startsWith('-') || arg === '-') {
        extras.push(arg);
        continue;
      }

      const equals = arg.indexOf('=');
      const optionString = equals === -1 ? arg : arg.slice(0, equals);
      const action = this.lookup(optionString);

      if (!action) {
        extras.push(arg);
        continue;
      }

      if (action.isHelp) {
        process.stdout.write(this.formatHelp());
        throw new SystemExit(0);
      }

      let raw;
      if (equals !== -1) {
        raw = arg.slice(equals + 1);
      } else if (i + 1 < argv.length) {
        i += 1;
        raw = argv[i];
      } else {
        this.error(`argument ${action.flags[0]}: expected one argument`);
      }

      const value = action.type.convert(raw);
      if (value === null) {
        this.error(
          `argument ${action.flags[0]}: invalid ${action.type.name} value: ${reprStr(raw)}`,
        );
      }

      namespace[action.dest] = value;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

