#!/usr/bin/env node
/**
 * Node.js port of dataset/construct/test17.py.
 *
 * Builds seven little-endian fields with the `construct` port and prints each
 * one's Python `repr()`. Frame lists mirror the original script's line numbers
 * so an uncaught build error reproduces the reference traceback.
 */

import construct from './lib/construct/index.mjs';
import { ArgumentParser, intType, strType } from './lib/cli/argparse.mjs';
import { pyMod } from './lib/python/int.mjs';
import { reprBytes } from './lib/python/repr.mjs';
import { encodeUtf8 } from './lib/python/utf8.mjs';
import { PythonException, SystemExit, printPythonTraceback } from './lib/python/traceback.mjs';

/**
 * Program name and script name are those of the reference build, so usage
 * text and tracebacks match it character for character.
 */
const PROG = 'test17_executable';
const SCRIPT = 'test17';

/** Frames for a failure raised at `line` inside `main()` of test17.py. */
const framesAt = (line) => [
  { file: 'test17.py', line: 32, name: '<module>' },
  { file: 'test17.py', line, name: 'main' },
];

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--a', { type: intType, required: true });
  parser.addArgument('--b', { type: intType, required: true });
  parser.addArgument('--c', { type: strType, required: true });
  parser.addArgument('--d', { type: intType, required: true });
  parser.addArgument('--e', { type: strType, required: true });
  parser.addArgument('--f', { type: intType, required: true });
  parser.addArgument('--g', { type: intType, required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const format1 = construct.Int8ul.build(args.a, framesAt(16));                          // 构建头字节
