#!/usr/bin/env node
// Randomized differential fuzz: raw stdout bytes + exit code must match.
import { execFileSync, spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test17_executable';
const WORDS = ['hello', 'world', 'data', 'xyz', '', "it's", 'a"b', "q'\"z", 'a\\b',
  'é', '中文', '😀', '\t\n\r', '\x00\x01\x7f', 'msg', 'longer_payload_here'];

const pick = (a) => a[Math.floor(Math.random() * a.length)];
const rint = (lo, hi) => Math.floor(Math.random() * (hi - lo + 1)) + lo;
const bytelen = (s) => Buffer.byteLength(s, 'utf8');

let pass = 0;
const failures = [];

for (let n = 0; n < 600; n += 1) {
  const c = pick(WORDS);
  const e = pick(WORDS);
  // Mostly well-formed, sometimes deliberately wrong so error paths get hit.
  const d = Math.random() < 0.75 ? bytelen(c) : rint(-2, 12);
  const g = Math.random() < 0.75 ? bytelen(e) : rint(-2, 12);
  const args = [
    '--a', String(Math.random() < 0.85 ? rint(0, 255) : rint(-5, 300)),
    '--b', String(Math.random() < 0.85 ? rint(0, 65535) : rint(-5, 65600)),
    '--c', c, '--d', String(d),
    '--e', e, '--g', String(g),
    '--f', String(Math.random() < 0.85 ? rint(0, 255) : rint(-5, 300)),
  ];

  const ref = spawnSync(REF, args, { encoding: 'buffer' });
  const js = spawnSync('node', ['/output/test17.mjs', ...args], { encoding: 'buffer' });

  const sameOut = ref.stdout.equals(js.stdout);
  const sameCode = ref.status === js.status;
  const strip = (b) => b.toString('utf8').split('\n').filter((l) => !l.startsWith('[PYI-')).join('\n');
  const sameErr = strip(ref.stderr) === strip(js.stderr);

  if (sameOut && sameCode && sameErr) {
    pass += 1;
  } else {
    failures.push({
      args,
      refOut: ref.stdout.toString(), jsOut: js.stdout.toString(),
      refCode: ref.status, jsCode: js.status,
      refErr: sameErr ? null : strip(ref.stderr), jsErr: sameErr ? null : strip(js.stderr),
    });
  }
}

console.log(`pass=${pass} fail=${failures.length}`);
for (const f of failures.slice(0, 5)) console.log(JSON.stringify(f, null, 2));

